   211	int PEM_bytes_read_bio(unsigned char **pdata, long *plen, char **pnm,
   212	                       const char *name, BIO *bp, pem_password_cb *cb,
   213	                       void *u)
   214	{
   215	    EVP_CIPHER_INFO cipher;
   216	    char *nm = NULL, *header = NULL;
   217	    unsigned char *data = NULL;
   218	    long len;
   219	    int ret = 0;
   220	
   221	    for (;;) {
   222	        if (!PEM_read_bio(bp, &nm, &header, &data, &len)) {
   223	            if (ERR_GET_REASON(ERR_peek_error()) == PEM_R_NO_START_LINE)
   224	                ERR_add_error_data(2, "Expecting: ", name);
   225	            return 0;
   226	        }
   227	        if (check_pem(nm, name))
   228	            break;
   229	        OPENSSL_free(nm);
   230	        OPENSSL_free(header);
   231	        OPENSSL_free(data);
   232	    }
   233	    if (!PEM_get_EVP_CIPHER_INFO(header, &cipher))
   234	        goto err;
   235	    if (!PEM_do_header(&cipher, data, &len, cb, u))
   236	        goto err;
   237	
   238	    *pdata = data;
   239	    *plen = len;
   240	
   241	    if (pnm)
   242	        *pnm = nm;
   243	
   244	    ret = 1;
   245	
   246	 err:
   247	    if (!ret || !pnm)
   248	        OPENSSL_free(nm);
   249	    OPENSSL_free(header);
   250	    if (!ret)
   251	        OPENSSL_free(data);
   252	    return ret;
   253	}
