   372	    *out_len = 0;
   373	    return -1;
   374	  }
   375	  *out_len = (int)bytes_out;
   376	
   377	  if (ctx->eof_seen) {
   378	    return 0;
   379	  }
   380	
   381	  return 1;
   382	}
